    if imp_user and not isinstance(imp_user, str):
        raise ValueError("Impersonated user must be a string")
    if dehydration_hooks and not isinstance(dehydration_hooks, dict):
        raise ValueError("Dehydration hooks must be a dict")
    if hydration_hooks and not isinstance(hydration_hooks, dict):
        raise ValueError("Hydration hooks must be a dict")
    if not handlers:
        handlers = {}

    begin_message = BeginMessage(
        mode,
        bookmarks,
        metadata,
        timeout,
        db,
        imp_user,
        dehydration_hooks,
        hydration_hooks,
    )
    self._append_message(begin_message)
    return Response(begin_message, handlers)

