def reset(self):
    """Reset the histogram.

    Current context is reset to an empty dict.
    Bins are reinitialized with the *initial_value*
    or with *make_bins* (depending on the initialization).
    """
    # Reset the current context
    self.current = {}

    # Reinitialize bins with the initial value or make_bins, depending on the initialization
    if hasattr(self, "make_bins"):
        self.bins = self.make_bins()
    else:
        self.bins = [self.initial_value] * len(self.bins)

def reset(self):
        """Reset the histogram.

        Current context is reset to an empty dict.
        Bins are reinitialized with the *initial_value*
        or with *make_bins()* (depending on the initialization).
        """
        # Reset the current context
        self._current_context = {}

        # Reinitialize the bins
        if hasattr(self, "_initial_value"):
            # Use the initial value if provided
            self._bins = {
                bin_key: self._initial_value
                for bin_key in self._bins
            }
        else:
            # Otherwise, use the make_bins function
            self._bins = self.make_bins()
            for k, v in self._current_context.items():
                self._bins[k]["value"] = v

