def fill(self, coord, weight=1):
    """Fill histogram at *coord* with the given *weight*.

    Coordinates outside the histogram edges are ignored.
    """

    if self.bins == None:
        raise ValueError("histogram has not been created yet")

    if len(coord) != len(self.bins):
        raise ValueError("coordinate length must match number of bins")

    for i in range(len(self.bins)):
        if coord[i] < self.bins[i][0] or coord[i] > self.bins[i][1]:
            return

    self.histogram[tuple(coord)] += weight

    if self.histogram[tuple(coord)] > self.max_value:
        self.max_value = self.histogram[tuple(coord)]

    if self.histogram[tuple(coord)] < self.min_value:
        self.min_value = self.histogram[tuple(coord)]

def _validate_labels(labels):
    errors = []
    for key, value in labels.items():
        if not isinstance(key, str) or key.startswith("$$"):
            errors.append({key: "Label key '$$' does not match the regex [...]"})
        if not isinstance(value, str) and not isinstance(value, bytes):
            errors.append({value: "expected string or bytes-like object"})
    if errors:
        raise ValidationError(errors)

def _validate_labels(labels):
    """Check that keys and values in the given labels match against their corresponding
    regular expressions.

    Args:
        labels (dict): the different labels to validate.

    Raises:
        ValidationError: if any of the keys and labels does not match their respective
            regular expression. The error contains as message the list of all errors
            which occurred in the labels. Each element of the list is a dictionary with
            one key-value pair:
            - key: the label key or label value for which an error occurred as string.
            - value: the error message.

            .. code:: python

                # Example:
                labels = {
                    "key1": "valid",
                    "key2": ["invalid"],
                    "$$": "invalid",
                    True: True,
                }
                try:
                    _validate_labels(labels)
                except ValidationError as err:
                    assert err.messages == [
                        {"['invalid']": 'expected string or bytes-like object'},
                        {'$$': "Label key '$$' does not match the regex [...]"},
                        {'True': 'expected string or bytes-like object'},
                        {'True': 'expected string or bytes-like object'},
                    ]
    """
    validation_errors = []
    for label_key, label_value in labels.items():
        try:
            _validate_label_key(label_key)
        except ValidationError as err:
            validation_errors.append({label_key: err.message})
        try:
            _validate_label_value(label_value)
        except ValidationError as err:
            validation_errors.append({label_value: err.message})

    if validation_errors:
        error_messages = []
        for err in validation_errors:
            for key, value in err.items():
                error_messages.append({key: value})
        raise ValidationError(message="\n".join(error_messages))

