def validate_as_prior_version(self, prior):
    """Check that prior is a valid prior version of the current inventory object.

    The input variable prior is also expected to be an InventoryValidator object
    and both self and prior inventories are assumed to have been checked for
    internal consistency.
    """

    # Check that all parameters in prior are present in self, and that their values
    # are not different from those in self.
    if self.parameters:
        for prior_param in prior.parameters:
            if prior_param not in self.parameters:
                raise ValueError(f'{prior_param} is not present in {self}')
            if prior.get_value(prior_param) != self.get_value(prior_param):
                raise ValueError(f'parameter {prior_param} has value {prior.get_value(prior_param)} in {prior} but value {self.get_value(prior_param)} in {self}')

    # Check that all species in prior are also present in self.
    if self.species:
        for prior_species in prior.species:
            if prior_species not in self.species:
                raise ValueError(f'{prior_species} is not present in {self}')

    # Check that the stoichiometry matrix of prior is a valid submatrix of the
    # stoichiometry matrix of self.
    if self.stoichiometry_matrix:
        prior_stoichiometry_matrix = prior.stoichiometry_matrix
        if np.abs(prior_stoichiometry_matrix - self.stoichiometry_matrix).max() > 1e-10:
            raise ValueError(f'{prior.stoichiometry_matrix} is not a submatrix of {self.stoichiometry_matrix}')

    # Check that the propensities of prior are generally less than those of self
    # for any rate constant that is present in both.
    if self.propensities:
        for prior_propensity in prior.propensities:
            self_propensity = self.get_propensity(prior_propensity)
            if self_propensity is not None and self_propensity < prior_propensity:
                raise ValueError(f'propensity for {prior_propensity} is greater than that for {self_propensity} in {self}')

    return True

