def validate_fixity(self, fixity, manifest_files):
    """Validate fixity block in inventory.

    Check the structure of the fixity block and makes sure that only files
    listed in the manifest are referenced.
    """
    if not isinstance(fixity, dict):
        raise TypeError("Fixity block must be a dictionary")

    if "fixities" not in fixity:
        raise ValueError("Fixity block must contain a 'fixities' key")

    fixities = fixity["fixities"]
    if not isinstance(fixities, dict):
        raise TypeError("Fixities must be a dictionary")

    for file_path,fixity in fixities.items():
        if file_path not in manifest_files:
            raise ValueError(f"File {file_path} is not listed in the manifest")

        if not isinstance(fixity, dict):
            raise TypeError(f"Fixity for {file_path} must be a dictionary")

        if "algorithm" not in fixity:
            raise ValueError(f"Fixity for {file_path} must contain an 'algorithm' key")

        if "value" not in fixity:
            raise ValueError(f"Fixity for {file_path} must contain a 'value' key")

        algorithm = fixity["algorithm"]
        value = fixity["value"]

        if not isinstance(algorithm, str):
            raise TypeError(f"Algorithm for {file_path} must be a string")

        if not isinstance(value, str):
            raise TypeError(f"Value for {file_path} must be a string")

        try:
            hashlib.new(algorithm)
        except ValueError:
            raise ValueError(f"Unsupported algorithm {algorithm} for {file_path}")

        try:
            encoded_value = codecs.encode(value, 'utf-8')
        except UnicodeError:
            raise ValueError(f"Invalid UTF-8 encoding for value of fixity for {file_path}")

        try:
            hash = hashlib.new(algorithm)
            hash.update(encoded_value)
            calculated_value = hash.hexdigest()
        except:
            raise ValueError(f"Failed to calculate hash for fixity of {file_path}")

        if calculated_value != value:
            raise ValueError(f"Invalid value for fixity of {file_path}, expected {calculated_value}")

