    Return the files in `path`
    """
    files = []
    for f in os.listdir(path):
        file_path = os.path.join(path, f)
        if os.path.isfile(file_path):
            files.append(file_path)
    return files

def _group_files_by_xml_filename(xml_filename, files):
    groups = {}
    for file in files:
        basename = os.path.basename(xml_filename)
        if basename not in groups:
            groups[basename] = []
        groups[basename].append(file)
    return groups

def _group_files_by_xml_filename(xml_filename, files):
    groups = {}
    for file in files:
        basename = os.path.basename(file)
        if basename.endswith('.xml'):
            name = basename[:-4]
            if name not in groups:
                groups[name] = Package(name, xml_filename)
            groups[name].files.append(file)
    return groups

def _group_files_by_xml_filename(source, xmls, files):
    """
    Group files by their XML basename

    Groups files by their XML basename and returns data in dict format.

    Parameters
    ----------
    xml_filename : str
        XML filenames
    files : list
        list of files in the folder or zipfile

    Returns
    -------
    dict
        key: name of the XML files
        value: Package
    """
    xml_filename = []
    for file in files:
        if file.endswith('.xml'):
            xml_filename.append(file)
    packages = {}
    for xml in xmls:
        package = Package(xml)
        packages[xml] = package
    for file in files:
        if file not in xml_filename:
            package = packages[os.path.splitext(file)[0] + '.xml']
            package.add_file(file)
    return packages

