def _explore_zipfile(zip_path):
    with zipfile.ZipFile(zip_path, 'r') as zipf:
        basename_to_fileinfo = {}
        for fileinfo in zipf.infolist():
            basename = os.path.basename(fileinfo.filename)
            if basename not in basename_to_fileinfo:
                basename_to_fileinfo[basename] = []
            basename_to_fileinfo[basename].append(fileinfo)

    packages_data = {}
    for basename, fileinfos in basename_to_fileinfo.items():
        xml_basename = os.path.splitext(basename)[0]
        if xml_basename not in packages_data:
            packages_data[xml_basename] = []
        for fileinfo in fileinfos:
            with zipf.open(fileinfo) as f:
                packages_data[xml_basename].append(f.read())

    return packages_data

def _explore_zipfile(zip_path):
    """
    Get packages' data from zip_path

    Groups files by their XML basename and returns data in dict format.

    Parameters
    ----------
    zip_path : str
        zip file path
    Returns
    -------
    dict
    """
    with zipfile.ZipFile(zip_path) as zf:
        file_list = zf.infolist()
        file_dict = {}
        for file in file_list:
            if file.filename.endswith('/') or file.filename.startswith('.'):
                continue
            name = os.path.splitext(file.filename)[0]
            if name not in file_dict:
                file_dict[name] = []
            file_dict[name].append(file)

        package_data = {}
        for name in file_dict:
            files = file_dict[name]
            xml_file = None
            for file in files:
                if file.filename.endswith('.xml'):
                    xml_file = file
                    break
            if xml_file:
                data = zf.read(xml_file)
                package_data[name] = {
                    'xml_data': data,
                    'python_file': [],
                    'js_file': []
                }
            for file in files:
                if file.filename.endswith('.py'):
                    package_data[name]['python_file'].append(file)
                elif file.filename.endswith('.js'):
                    package_data[name]['js_file'].append(file)

    return package_data

