def _extract_number_and_supplment_from_issue_element(issue):
    numbers = []
    supplements = []
    for token in issue.split():
        if token.isdigit():
            numbers.append(token)
        elif token.lower() in ["spe", "spepr", "spe.2", "suppl", "suppl.", "supplpr"]:
            supplements.append(token)
    if len(numbers) == 0:
        numbers.append("1")
    if len(supplements) == 0:
        supplements.append("")
    return numbers[0], supplements[0]

def pretty(self, indent=0, debug=False):
    """
    Return a pretty formatted representation of self.
    """
    result = ''
    indent_space = ' ' * indent
    for key, value in self.__dict__.items():
        if debug and key.startswith('_'):
            continue
        if isinstance(value, list):
            result += f'{indent_space}{key}:\n{indent_space}'
            for item in value:
                result += f'{item}\n'
                result += f'{indent_space}'
            result += f'\n'
        else:
            result += f'{indent_space}{key}: {value}\n'
    return result

def pretty(self, indent=0, debug=False):
    """
    Return a pretty formatted representation of self.
    """
    if debug:
        output = []
        for k, v in self.get_items():
            output.append(f"{k}: {v}")
        return "\n".join(output)
    else:
        return json.dumps(self.get_items(), indent=indent)

def absorb(self, args):
    """
    Given an `args` sequence of expressions, return a new list of expression
    applying absorption and negative absorption.

    See https://en.wikipedia.org/wiki/Absorption_law

    Absorption::

        A & (A | B) = A, A | (A & B) = A

    Negative absorption::

        A & (~A | B) = A & B, A | (~A & B) = A | B
    """
    # Apply absorption and negative absorption
    new_args = []
    for arg in args:
        if isinstance(arg, BinOp) and arg.op == '&':
            if arg.right.op == '|' and arg.right.right.op == '~':
                # Apply negative absorption
                new_args.append(arg.left & arg.right.right.right)
            elif arg.left.op == '|' and arg.left.right.op == '~':
                # Apply negative absorption
                new_args.append(arg.right & arg.left.right.right)
            else:
                # Apply absorption
                new_args.append(arg.left | arg.right)
        elif isinstance(arg, BinOp) and arg.op == '|':
            if arg.right.op == '&' and arg.right.right.op == '~':
                # Apply negative absorption
                new_args.append(arg.left & arg.right.right.right)
            elif arg.left.op == '&' and arg.left.right.op == '~':
                # Apply negative absorption
                new_args.append(arg.right & arg.left.right.right)
            else:
                # Apply absorption
                new_args.append(arg.left | arg.right)
        else:
            new_args.append(arg)
    return new_args

def absorb(self, args):
    """
    Given an `args` sequence of expressions, return a new list of expression
    applying absorption and negative absorption.

    See https://en.wikipedia.org/wiki/Absorption_law

    Absorption::

        A & (A | B) = A, A | (A & B) = A

    Negative absorption::

        A & (~A | B) = A & B, A | (~A & B) = A | B
    """
    new_args = []
    for arg in args:
        if isinstance(arg, Or):
            if any(isinstance(operand, Not) and operand.expr == arg.expr for operand in arg.operands):
                continue
            new_args.extend(arg.operands)
        elif isinstance(arg, And):
            if any(isinstance(operand, Not) and operand.expr == arg.expr for operand in arg.operands):
                new_args.append(False)
            else:
                new_args.extend(arg.operands)
        else:
            new_args.append(arg)
    return new_args

