def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    if not isinstance(commands, list):
        raise TypeError("commands must be a list")

    if not commands:
        return

    for command in commands:
        if not isinstance(command, str):
            raise TypeError("each command must be a string")

        cmd_parts = shlex.split(command)
        cmd_name = cmd_parts[0]
        cmd_args = cmd_parts[1:]

        if verbose:
            print("Running command:", command)

        try:
            subprocess.check_call(cmd_parts, cwd=cwd, env=env)
        except subprocess.CalledProcessError as e:
            if hide_stderr:
                print("Error: command '{}' failed with exit code {}".format(cmd_name, e.returncode), file=sys.stderr)
            else:
                print("Error: command '{}' failed with exit code {} and output:".format(cmd_name, e.returncode), file=sys.stderr)
                print(e.stdout.decode("utf-8"), file=sys.stderr)
            sys.exit(1)

def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    if isinstance(commands, str):
        commands = [commands]

    for command in commands:
        if verbose:
            print("Running command:", command)

        if env is not None:
            for key, value in env.items():
                os.environ[key] = value

        try:
            subprocess.check_call(command, cwd=cwd, stderr=subprocess.STDOUT, shell=True)
        except subprocess.CalledProcessError as e:
            if hide_stderr:
                print("Error:", e.output.decode("utf-8"))
            else:
                print("Error:", e)
            return False
        except Exception as e:
            print("Error:", e)
            return False

    return True

def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
