            subprocess.check_output(command, stderr=subprocess.STDOUT, shell=False)
    except subprocess.CalledProcessError as e:
        if verbose:
            print(e.output)
        raise ProgramError(f"command '{command}' failed") from e
    else:
        if verbose:
            print(f"command '{command}' finished successfully")

def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    if not isinstance(commands, list):
        commands = [commands]

    for command in commands:
        if verbose:
            print("Running command:", command)
        try:
            if cwd:
                proc = subprocess.Popen(command, cwd=cwd,
                                        stdout=subprocess.PIPE, stderr=subprocess.PIPE)
            else:
                proc = subprocess.Popen(command, stdout=subprocess.PIPE,
                                        stderr=subprocess.PIPE)
            stdout, stderr = proc.communicate()
            if proc.returncode != 0:
                raise ProgramError("Command '{}' failed with exit code {}".format(command, proc.returncode))
            if hide_stderr:
                stderr = None
            if env:
                for var in env:
                    os.environ[var] = env[var]

            if verbose:
                print("stdout:", stdout)
                print("stderr:", stderr)

            return stdout, stderr
        except (OSError, IOError) as e:
            raise ProgramError("Error running command '{}': {}".format(command, e))

def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    if isinstance(commands, str):
        commands = [commands]
    for command in commands:
        try:
            subprocess.check_call(command, args, cwd=cwd, env=env)
        except subprocess.CalledProcessError as e:
            if hide_stderr:
                print(e.output)
            else:
                print(e)
            return e.returncode
    return 0

