def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
    """Validate storage root hierarchy.

    Returns:
        num_objects - number of objects checked
        good_objects - number of objects checked that were found to be valid
    """
    num_objects = 0
    good_objects = 0
    unknown_objects = 0
    for obj_id in self.get_child_ids():
        num_objects += 1
        obj = self.get_object(obj_id)
        if obj is None:
            unknown_objects += 1
        elif validate_objects and not obj.is_valid():
            if show_warnings:
                print(f"Object {obj_id} is invalid")
        else:
            good_objects += 1
    if unknown_objects > 0:
        if show_warnings:
            print(f"Unknown objects found: {unknown_objects}")
    return num_objects, good_objects

def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
    """Validate storage root hierarchy.

    Returns:
        num_objects - number of objects checked
        good_objects - number of objects checked that were found to be valid
    """
    num_objects = 0
    good_objects = 0
    if validate_objects:
        for obj_id in self._hierarchy:
            num_objects += 1
            if self.has_object(obj_id):
                good_objects += 1
            else:
                if show_warnings:
                    print(f"Object {obj_id} not found in storage.")
    if check_digests:
        for obj_id, digest in self._digests.items():
            if obj_id not in self._hierarchy:
                if show_warnings:
                    print(f"Object {obj_id} not found in hierarchy.")
            elif digest != self._compute_digest(obj_id):
                if show_warnings:
                    print(f"Object {obj_id} has invalid digest.")
    return num_objects, good_objects

def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
    """Validate storage root hierarchy.

    Returns:
        num_objects - number of objects checked
        good_objects - number of objects checked that were found to be valid
    """
    num_objects = 0
    good_objects = 0
    for object_id in self.root.object_map:
        num_objects += 1
        if validate_objects:
            if not self.root.object_map[object_id].validate(check_digests):
                if show_warnings:
                    print(f"WARNING: Object {object_id} failed validation")
            else:
                good_objects += 1
        else:
            good_objects += 1
    return num_objects, good_objects

def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
    """Validate storage root hierarchy.

    Returns:
        num_objects - number of objects checked
        good_objects - number of objects checked that were found to be valid
    """
    num_objects = 0
    good_objects = 0
    for collection in self._hierarchy:
        for object_bank in collection:
            num_objects += 1
            if validate_objects:
                if not object_bank.is_valid():
                    print(f"Object {object_bank.id} is not valid")
                    continue
            if check_digests:
                if not object_bank.check_digest():
                    print(f"Object {object_bank.id} has invalid digest")
                    continue
            good_objects += 1
