def next_version(version):
    """Next version identifier following existing pattern.

    Must deal with both zero-prefixed and non-zero prefixed versions.
    """
    if not version:
        return "1.0.0"

    version_parts = version.split(".")
    if len(version_parts) == 1:
        return f"{version[0] + 1}.0.0"
    elif len(version_parts) == 2:
        return f"{version_parts[0]}.{version_parts[1][0] + 1}.0"
    else:
        return f"{version_parts[0]}.{version_parts[1]}.{version_parts[2][0] + 1}"

def next_version(version):
    """Next version identifier following existing pattern.

    Must deal with both zero-prefixed and non-zero prefixed versions.
    """

    pattern = r"^[vV]?(\d+)\.(\d+)\.(\d+)(?:-\w*)?$"
    match = re.match(pattern, version)
    if match:
        major, minor, patch = match.groups()
        if patch.startswith("0"):
            patch = patch[1:]
        return f"v{major}.{minor}.{int(patch) + 1}"
    else:
        raise ValueError(f"Invalid version string: {version}")

def validate_version_inventories(self, version_dirs):
    """Each version SHOULD have an inventory up to that point.

    Also keep a record of any content digests different from those in the root inventory
    so that we can also check them when validating the content.

    version_dirs is an array of version directory names and is assumed to be in
    version sequence (1, 2, 3...).
    """
    for version_dir in version_dirs:
        inventory_file = os.path.join(version_dir, "inventory")
        if not os.path.exists(inventory_file):
            raise ValueError(f"Missing inventory for version {version_dir}")

        with open(inventory_file, "r") as f:
            inventory = json.load(f)
            for digest in inventory:
                if digest not in self.root_inventory:
                    self.content_digests[digest] = inventory[digest]

def validate_version_inventories(self, version_dirs):
    """Validate version inventories."""
    root_inventory = self.load_root_inventory()
    # Check that each version directory has an inventory.
    for version_dir in version_dirs:
        inventory_path = os.path.join(version_dir, "inventory")
        if not os.path.exists(inventory_path):
            raise ValueError(f"Missing inventory for version {version_dir}")
        inventory = self.load_inventory(inventory_path)
        # Check that each file in the inventory has the same digest as the root inventory.
        for file_name, digest in inventory.items():
            if digest != root_inventory.get(file_name):
                raise ValueError(f"Mismatched digest for file {file_name} in inventory {version_dir}")
    # Record any content digests different from those in the root inventory.
    for version_dir in version_dirs:
        inventory = self.load_inventory(os.path.join(version_dir, "inventory"))
        for file_name, digest in inventory.items():
            if digest != root_inventory.get(file_name):
                self.differing_digests[file_name] = digest
    return self.differing_digests

def find_path_type(path):
    """Return a string indicating the type of thing at the given path.

    Return values:
        'root' - looks like an OCFL Storage Root
        'object' - looks like an OCFL Object
        'file' - a file, might be an inventory
        other string explains error description

    Looks only at "0=*" Namaste files to determine the directory type.
    """
    if not os.path.exists(path):
        return "not found"
    if not os.path.isdir(path):
        return "not a directory"
    for root, dirs, files in os.walk(path):
        if "0=*" in files:
            return "root"
        for d in dirs:
            if os.path.isdir(os.path.join(root, d)):
                if "0=*" in os.listdir(os.path.join(root, d)):
                    return "object"
    return "file"

def find_path_type(path):
    """Return a string indicating the type of thing at the given path.

    Return values:
        'root' - looks like an OCFL Storage Root
        'object' - looks like an OCFL Object
        'file' - a file, might be an inventory
        other string explains error description

    Looks only at "0=*" Namaste files to determine the directory type.
    """
    namaste_file = None
    for root, dirs, files in os.walk(path):
        for file in files:
            if file.startswith("0=*"):
                namaste_file = os.path.join(root, file)
                break
        if namaste_file:
            break

    if not namaste_file:
        return "file"

    with open(namaste_file, "r") as f:
        content = f.read()

    if "OCFL" in content and "Storage" in content:
        return "root"
    elif "OCFL" in content and "Inventory" in content:
        return "object"
    else:
        return "file"

def find_path_type(path):
    # Iterate through the "0=*" Namaste files in the directory to determine the directory type
    for file in os.listdir(path):
        # Check if the file is a Namaste file with a "0=*" header
        if re.match(r"^0=.*$", file):
            # Parse the first line of the file to determine the file type
            with open(file, "r") as f:
                line = f.readline()
                if re.match(r"^\s*OCFL\s*Object.*$", line):
                    return "object"
                elif re.match(r"^\s*OCFL\s*Storage\s*Root.*$", line):
                    return "root"
                else:
                    return "file"
    # If no Namaste files were found, return an error message
    return "no Namaste files found in directory"

