def parse_subparser_arguments(unparsed_arguments, subparsers):
    """
    Given a sequence of arguments and a dict from subparser name to argparse.ArgumentParser
    instance, give each requested action's subparser a shot at parsing all arguments. This allows
    common arguments like "--repository" to be shared across multiple subparsers.

    Return the result as a tuple of (a dict mapping from subparser name to a parsed namespace of
    arguments, a list of remaining arguments not claimed by any subparser).
    """
    subparser_args = {}
    remaining_args = []

    for argument in unparsed_arguments:
        subparser_name = None
        for name, parser in subparsers.items():
            try:
                namespace = parser.parse_known_args(argument)
                subparser_args[name] = namespace
                subparser_name = name
                break
            except argparse.ArgumentError:
                pass
        if subparser_name is None:
            remaining_args.append(argument)

    return subparser_args, remaining_args

def parse_subparser_arguments(unparsed_arguments, subparsers):
    """
    Given a sequence of arguments and a dict from subparser name to argparse.ArgumentParser
    instance, give each requested action's subparser a shot at parsing all arguments. This allows
    common arguments like "--repository" to be shared across multiple subparsers.

    Return the result as a tuple of (a dict mapping from subparser name to a parsed namespace of
    arguments, a list of remaining arguments not claimed by any subparser).
    """
    parsed_subparsers = {}
    remaining_arguments = []

    # Iterate over the unparsed arguments and try to parse them with each subparser
    for argument in unparsed_arguments:
        for subparser_name, subparser in subparsers.items():
            try:
                # Attempt to parse the argument using the current subparser
                namespace = subparser.parse_known_args(argument)
                parsed_subparsers[subparser_name] = namespace
                break
            except argparse.ArgumentError:
                # If the subparser can't parse the argument, try the next one
                pass
        else:
            # If no subparser was able to parse the argument, add it to the remaining arguments
            remaining_arguments.append(argument)

    return (parsed_subparsers, remaining_arguments)

