def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    """
    Convert a number to a string, using the given alphabet.

    The output has the most significant digit first.
    """
    if padding is None:
        padding = len(alphabet)

    result = ""
    base = len(alphabet)
    while number > 0:
        number, remainder = divmod(number, base)
        result = alphabet[remainder] + result

    return result.rjust(padding, alphabet[0])

def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    if padding is None:
        padding = len(str(number))
    output = []
    for i in range(padding):
        output.append(alphabet[number % len(alphabet)])
        number //= len(alphabet)
    return "".join(reversed(output))

def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    """
    Convert a number to a string, using the given alphabet.

    The output has the most significant digit first.
    """
    if not isinstance(number, int):
        raise ValueError("'number' must be an integer")
    if not isinstance(alphabet, list):
        raise ValueError("'alphabet' must be a list")
    if not all(isinstance(symbol, str) for symbol in alphabet):
        raise ValueError("'alphabet' must contain only strings")
    if not all(len(symbol) == 1 for symbol in alphabet):
        raise ValueError("'alphabet' must contain only single-character strings")
    if not set(alphabet).isdisjoint(string.digits + string.ascii_letters):
        raise ValueError("'alphabet' should not contain digits or ascii letters")
    base = len(alphabet)
    if number == 0:
        return alphabet[0]
    chars = []
    while number > 0:
        number, remainder = divmod(number, base)
        chars.append(alphabet[remainder])
    chars.reverse()
    if padding is not None:
        chars.extend([alphabet[0]] * padding)
    return "".join(chars)

