def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    if isinstance(commands, str):
        commands = [commands]

    if not isinstance(args, list):
        raise ValueError("args must be a list")

    if cwd is not None and not os.path.isdir(cwd):
        raise ValueError("cwd must be a directory")

    if env is not None and not isinstance(env, dict):
        raise ValueError("env must be a dictionary")

    for command in commands:
        if verbose:
            print(f"Running command {command} with args {args}...")

        try:
            result = subprocess.run(
                command,
                args=args,
                cwd=cwd,
                stdout=subprocess.PIPE,
                stderr=subprocess.PIPE,
                env=env,
            )

            if hide_stderr:
                result.stderr = None

            if verbose:
                print(result.stdout.decode("utf-8"))

            return result.returncode, result.stdout, result.stderr
        except Exception as e:
            print(e)
            return None, None, None

def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""

    p = subprocess.Popen(commands, cwd=cwd, stdout=subprocess.PIPE, stderr=subprocess.PIPE, env=env)

    if hide_stderr:
        p.stderr = subprocess.DEVNULL

    if verbose:
        print("Running command:", commands)

    out, err = p.communicate()

    if p.returncode == 0:
        return out.decode("utf-8")
    else:
        raise subprocess.CalledProcessError(p.returncode, commands)

def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""

    if not isinstance(commands, list):
        commands = [commands]

    for command in commands:
        if verbose:
            print(f"Running command: {command} {args}")

        result = subprocess.run(command, args, cwd, env)

        if result.returncode != 0:
            if hide_stderr:
                print(f"Command failed: {command} {args}")
            else:
                print(f"Command failed: {command} {args}")
                print(f"Error: {result.stderr}")

            return result.returncode

    return 0

