def load_configurations(config_filenames, overrides=None, resolve_env=True):
    """
    Given a sequence of configuration filenames, load and validate each configuration file. Return
    the results as a tuple of: dict of configuration filename to corresponding parsed configuration,
    and sequence of logging.LogRecord instances containing any parse errors.
    """
    configs = {}
    records = []

    for filename in config_filenames:
        try:
            with open(filename, "r") as f:
                config = yaml.safe_load(f)
                configs[filename] = config
        except OSError as e:
            records.append(logging.LogRecord("Configuration file not found: %s", filename, logging.ERROR, filename,
                                             None, None, e))
        except yaml.YAMLError as e:
            records.append(logging.LogRecord("Invalid YAML in configuration file: %s", filename, logging.ERROR, filename,
                                             None, None, e))

    if overrides:
        for key, value in overrides.items():
            for filename, config in configs.items():
                if key in config:
                    config[key] = value

    if resolve_env:
        for filename, config in configs.items():
            for key, value in config.items():
                if isinstance(value, str) and value.startswith("env:"):
                    config[key] = os.getenv(value[4:], None)

    return configs, records

def load_configurations(config_filenames, overrides=None, resolve_env=True):
    """
