    if explicit_mc:
        metaclass = explicit_mc
    elif any(isinstance(base, ClassDef) and base.metaclass for base in bases):
        metaclass = next(base.metaclass for base in bases if isinstance(base, ClassDef) and base.metaclass)
    else:
