def determineMetaclass(bases, explicit_mc=None):
    """Determine metaclass from 1+ bases and optional explicit __metaclass__"""
    if not isinstance(bases, list):
        raise TypeError("determineMetaclass() must be called with a list of base classes.")
    if (len(bases) < 1 or len(bases) > 2
        or any(not isinstance(base, type) for base in bases)):
        raise TypeError("determineMetaclass() must be called with a list of base classes.")

    meta_cls_list = []
    for base in bases:
        # Get the metaclass from the base class
        base_meta = getattr(base, "__metaclass__", None)
        if base_meta:
            meta_cls_list.append(base_meta)

    if explicit_mc:
        meta_cls_list.append(explicit_mc)

    if not meta_cls_list:
        return type

    if len(meta_cls_list) == 1:
        return meta_cls_list[0]

    # Multiple metaclasses
    return type(meta_cls_list[0], meta_cls_list[1], {})

