    """Determine metaclass from 1+ bases and optional explicit __metaclass__"""
    # Return explicit metaclass if given
    if explicit_mc is not None:
        return explicit_mc

    # Check for metaclass conflicts
    metaclasses = {base.__class__ for base in bases}
    if len(metaclasses) > 1:
        raise TypeError("Metaclass conflict: %s" % bases)

    # Return the single metaclass
    return metaclasses.pop() if metaclasses else type

def pop(self, key, default=__marker):
    """
    D.pop(k[,d]) -> v, remove specified key and return the corresponding value.
    If key is not found, d is returned if given, otherwise KeyError is raised.
    """
    if key not in self:
        if default is not __marker:
            return default
        raise KeyError(key)
    for map in [self._pb.IntMap, self._pb.FloatMap, self._pb.StringMap,
                self._pb.BoolMap]:
        if key in map.keys():
            return map.pop(key)

