def process_text_links(text):
    """Process links in text, adding some attributes and linkifying textual links."""
    # Define a function to add attributes to links
    def add_attributes(url):
        if url.startswith("http"):
            return f'target="_blank" href="{url}"'
        else:
            return f'href="{url}"'

    # Use a regular expression to find all links in the text
    link_regex = r"\[([^\[]+)\]\(([^\)]+)\)"
    matches = re.findall(link_regex, text)

    # Iterate over the matches and add attributes to the links
    for match in matches:
        text = text.replace(match[0], f'<a {add_attributes(match[1])}>{match[0]}</a>')

    return text

