def verify_relayable_signature(public_key, doc, signature):
    """
    Verify the signed XML elements to have confidence that the claimed
    author did actually generate this message.
    """
    from cryptography.hazmat.primitives import hashes
    from cryptography.exceptions import InvalidSignature

    def _get_hash_type(algorithm):
        if algorithm == "rsa-sha256":
            return hashes.SHA256()
        else:
            raise ValueError("Unsupported signature algorithm: %s" % algorithm)

    def _get_public_key(key_info):
        return None  # Return the public key object

    hash_type = _get_hash_type(signature.algorithm)

    # Verify the signature
    try:
        public_key.verify(
            signature,
            doc.tostring(),
            padding.PKCS1v15(),
            hash_type
        )
    except InvalidSignature:
        return False

    return True

