def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    try:
        data = json.loads(document)
        if "links" in data:
            links = data["links"]
        else:
            logger.warning("parse_diaspora_webfinger: invalid webfinger JSON document")
            return None
    except json.decoder.JSONDecodeError:
        tree = ET.fromstring(document)
        if tree.tag != "XRD":
            logger.warning("parse_diaspora_webfinger: invalid webfinger XRD document")
            return None
        links = []
        for elem in tree.findall("Link"):
            links.append(
                {
                    "rel": elem.attrib["rel"],
                    "type": elem.attrib["type"],
                    "href": elem.attrib["href"],
                }
            )
    return {"links": links}

def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    try:
        webfinger_data = json.loads(document)
        if webfinger_data["subject"] == document:
            return webfinger_data
        else:
            raise ValueError("Invalid webfinger document")
    except (ValueError, KeyError):
        # If the webfinger document is not in JSON format, it's likely in XRD format
        try:
            xrd_tree = etree.fromstring(document)
            subject_node = xrd_tree.find(".//{urn:xmpp:tmp:rd:3}Subject")
            if subject_node is not None and subject_node.text == document:
                return {
                    "subject": document,
                    "links": [
                        {
                            "rel": link_node.get("rel"),
                            "type": link_node.get("type"),
                            "href": link_node.get("href"),
                        }
                        for link_node in xrd_tree.find(".//{urn:xmpp:tmp:rd:3}Link")
                    ],
                }
            else:
                raise ValueError("Invalid webfinger document")
        except (etree.XMLSyntaxError, ValueError):
            raise ValueError("Invalid webfinger document")

def parse_diaspora_webfinger(document: str) -> Dict:
