def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    try:
        json_data = json.loads(document)
        return json_data
    except json.decoder.JSONDecodeError:
        pass

    try:
        xml_doc = ET.fromstring(document)
    except ET.ParseError:
        return None

    namespace = "http://docs.oasis-open.org/ns/xri/xrd-1.0"
    xrd = xml_doc.find("{%s}XRD" % namespace)
    if xrd is None:
        return None

    aliases = []
    properties = {}
    links = {}
    for child in xrd.findall(".//{%s}*[not(%s) and not(%s)]" % (
        namespace,
        "{%s}Subject" % namespace,
        "{%s}Link" % namespace,
    )):
        tag = child.tag.split("}", 1)[-1]
        value = child.text
        if tag == "Alias":
            aliases.append(value)
        elif tag == "Property":
            properties[value.get("type")] = value.text
        elif tag == "Link":
            links[value.get("rel")] = value.get("href")

    return {"aliases": aliases, "properties": properties, "links": links}

def try_retrieve_webfinger_document(handle: str) -> Optional[str]:
    """
    Try to retrieve an RFC7033 webfinger document. Does not raise if it fails.
    """
    try:
        host = handle.split("@")[1]
    except AttributeError:
        logger.warning("try_retrieve_webfinger_document: invalid handle given: %s", handle)
        return None
    document, code, exception = fetch_document(
        host=host, path="/.well-known/webfinger?resource=acct:%s" % quote(handle),
    )
    if document:
        return document
    hostmeta = retrieve_diaspora_host_meta(host)
    if not hostmeta:
        return None
    url = hostmeta.find_link(rels="lrdd").template.replace("{uri}", quote(handle))
    document, code, exception = fetch_document(url)
    if exception:
        return None
    return document

