def validate_from_content(spec_content=None):
    """validates that spec (YAML) content has all required fields

    :param spec_content: content of spec file
    :raise IRValidatorException: when mandatory data
    is missing in spec file
    :return: Dictionary with data loaded from a spec (YAML) file
    """
    if not spec_content:
        raise IRValidatorException("Missing spec content")

    try:
        data = yaml.safe_load(spec_content)
    except yaml.YAMLError as e:
        raise IRValidatorException("Invalid YAML data") from e

    # validate data
    required_fields = ["pipeline", "stages"]
    for field in required_fields:
        if field not in data:
            raise IRValidatorException(f"Missing required field '{field}'")

    return data

def validate_from_file(cls, yaml_file=None):
    """Loads & validates that a YAML file has all required fields

    :param yaml_file: Path to YAML file
    :raise IRValidatorException: when mandatory data is missing in file
    :return: Dictionary with data loaded from a YAML file
    """
    with open(yaml_file, 'r') as stream:
        try:
            data = yaml.safe_load(stream)
        except yaml.YAMLError as exc:
            print(exc)

    required_fields = ['recipe_name', 'recipe_version', 'ingredients', 'servings']
    for field in required_fields:
        if field not in data:
            raise IRValidatorException('Missing mandatory key in YAML file: {}'.format(field))

    if 'ingredients' in data:
        for ingredient in data['ingredients']:
            if 'quantity' not in ingredient or 'unit' not in ingredient or 'name' not in ingredient:
                raise IRValidatorException('Ingredient missing required fields: {}'.format(ingredient))
            if 'notes' in ingredient:
                for note in ingredient['notes']:
                    if note == 'optional':
                        continue
                    raise IRValidatorException('Invalid note in ingredient: {}'.format(note))
    return data

