def _include_groups(self, parser_dict):
    """Resolves the include dict directive in the spec files. """
    for key, value in parser_dict.items():
        if key == "include":
            for group, group_dict in value.items():
                parser_dict.setdefault(group, OrderedDict())
                for arg, arg_dict in group_dict.items():
                    parser_dict[group][arg] = arg_dict
    return parser_dict

def _include_groups(self, parser_dict):
    """Resolves the include dict directive in the spec files.

    :param dict parser_dict:
    """
    includes = parser_dict.get('include', [])
    for include in includes:
        if not isinstance(include, dict):
            continue
        elif len(include) != 1:
            continue
        group, options = list(include.items())[0]
        import utool as ut
        if isinstance(options, str):
            options = self._parse_group_yaml(options)
        if not isinstance(options, dict):
            ut.debug('Invalid include directive in %s: %s' % (group, options))
            continue
        parser_dict[group] = options

def _include_groups(self, parser_dict):
    """Resolves the include dict directive in the spec files. """
    import six
    parser_sections = parser_dict.get('__init__', {}).get('sections', [])
    for section in parser_sections:
        section_name = section.pop('_include', None)
        if section_name:
            section_data = parser_dict.get(section_name, {}).get('data', None)
            if section_data:
                for key, value in six.iteritems(section_data):
                    if key not in section:
                        section[key] = value
    return parser_dict

def _include_groups(self, parser_dict):
    """Resolves the include dict directive in the spec files. """
    grouped_data = defaultdict(list)
    for key, value in parser_dict.items():
        if isinstance(value, dict):
            grouped_data[value['group']].append(key)
    return grouped_data

def _include_groups(self, parser_dict):
    """Resolves the include dict directive in the spec files."""

    for key, value in parser_dict.items():
        if isinstance(value, dict):
            self._include_groups(value)
            parser_dict[key] = self._build_argument_group(value)
        elif isinstance(value, list):
            for item in value:
                if isinstance(item, dict):
                    self._include_groups(item)
                    item = self._build_argument_group(item)
            parser_dict[key] = value
        else:
            parser_dict[key] = value

def get_spec_defaults(self):
    """Resolve arguments' values from spec and other sources.

    Returns:
        dict: A dictionary of resolved arguments and their values.
    """
    resolved_args = {}

    for arg in self.args:
        # If the argument is a subparser, resolve its defaults recursively
        if isinstance(arg, Subparser):
            resolved_args.update(arg.get_spec_defaults())

        # If the argument has a default value, add it to the resolved args
        if not isinstance(arg.default, NoDefault):
            resolved_args[arg.name] = arg.default

        # If the argument is a dictionary, resolve its default values recursively
        if isinstance(arg, DictOption):
            if arg.scheme:
                resolved_args[arg.name] = arg.scheme.get_spec_defaults()

    return resolved_args

def get_spec_defaults(self):
    """Resolve arguments' values from spec and other sources.

    Returns:
        dict: The default configurations as set by the spec and other sources.

    Raises:
        errors.InvalidSchemeError: The spec does not contain valid options.
    """
    defaults = {}
    for arg in self.args:
        if not isinstance(arg, _BaseOpt):
            raise errors.InvalidSchemeError('Unable to build default for non-Option type')

        # if there is a default set, add it to the defaults dict
        if not isinstance(arg.default, NoDefault):
            defaults[arg.name] = arg.default

        # if we have a dict option, build the defaults for its scheme.
        # if any defaults exist, use them.
        if isinstance(arg, DictOption):
            if arg.scheme:
                b = arg.scheme.build_defaults()
                if b:
                    defaults[arg.name] = b

    # if the spec has any default values, use them.
    if self.spec:
        for k, v in self.spec.items():
            if k in defaults:
                raise errors.InvalidSchemeError(f'Duplicate default value for {k}')
            defaults[k] = v

    return defaults

