    """
    # Check for deprecated arguments in the answer file
    if answer_file_args:
        for arg in answer_file_args.keys():
            if arg in DEPRECATED_ARGS:
                print(f"WARNING: Argument '{arg}' is deprecated and will be removed in a future version.")

    # Check for deprecated arguments in the cli arguments
    if cli_args:
        for arg in cli_args.keys():
            if arg in DEPRECATED_ARGS:
                print(f"WARNING: Argument '{arg}' is deprecated and will be removed in a future version.")

def validate_arg_deprecation(cli_args, answer_file_args):
