    :param cli_args: the dict of arguments from cli
    :param answer_file_args:  the dict of arguments from files
    """
    # Check for deprecated arguments in the answer file
    for arg in answer_file_args:
        if arg in DEPRECATED_ARGS:
            warn_deprecated_arg(arg, DEPRECATED_ARGS[arg])

    # Check for deprecated arguments on the command line
    for arg in cli_args:
        if arg in DEPRECATED_ARGS and DEPRECATED_ARGS[arg] not in cli_args:
            warn_deprecated_arg(arg, DEPRECATED_ARGS[arg])

