def _get_conditionally_required_args(command_name, options_spec, args):
    # Get the options that have a required_when condition
    required_options = [
        option
        for option in options_spec
        if hasattr(option, "required_when")
    ]

    # Get the required arg names for each option
    required_args = set()
    for option in required_options:
        if option.required_when(command_name, args):
            required_args.update(
                name for name, value in option.arguments if value is not None
            )

    return list(required_args)

def _get_conditionally_required_args(self, command_name, options_spec, args):
    """List arguments with ``required_when`` condition matched.

    :param command_name: the command name.
    :param options_spec:  the list of command spec options.
    :param args: the received input arguments
    :return: list, list of argument names with matched ``required_when``
        condition
    """
    conditionally_required_args = []
    for opt in options_spec:
        if opt.get('required_when'):
            condition = opt['required_when']
            if isinstance(condition, str):
                condition = [condition]
            for c in condition:
                if c in args:
                    conditionally_required_args.append(opt['name'])
                    break
    return conditionally_required_args

