def create_complex_argumet_type(subcommand, type_name, option_name, spec_option):
    """Build the complex argument type

    :param subcommand: the command name
    :param type_name: the complex type name
    :param option_name: the option name
    :param spec_option: option's specifications
    :return: the complex type instance
    """
    if type_name == 'str':
        return StringType(name=option_name)
    if type_name == 'int':
        return IntegerType(name=option_name)
    if type_name == 'float':
        return FloatType(name=option_name)
    if type_name == 'bool':
        return BoolType(name=option_name)
    if type_name == 'list':
        return ListType(name=option_name, element_type=spec_option['element_type'])
    if type_name == 'dict':
        return DictType(name=option_name, element_type=spec_option['element_type'])
    raise ValueError(f"Unsupported type: {type_name}")

def get_nested_custom_and_control_args(self, args):
    """Split input arguments to control nested and custom.

    Controls arguments: control the IR behavior. These arguments
        will not be put into the spec yml file
    Nested arguments: are used by the Ansible playbooks and will be put
        into the spec yml file.
    Custom arguments: Custom ansible variables to be used instead of the
        normal nested usage.

    :param args: the collected list of args.
    :return: (dict, dict): flat dicts (control_args, nested_args)
    """
    control_args = {}
    nested_args = {}
    custom_args = {}

    for key, value in args.items():
        if key.startswith('control_'):
            control_args[key.replace('control_', '')] = value
        elif key.startswith('nested_'):
            nested_args[key.replace('nested_', '')] = value
        elif key.startswith('custom_'):
            custom_args[key.replace('custom_', '')] = value

    return control_args, nested_args, custom_args

