def merge_extra_vars(vars_dict, extra_vars=None):
    if extra_vars is None:
        return vars_dict
    vars_dict.update(extra_vars)
    return vars_dict

def merge_extra_vars(vars_dict, extra_vars=None):
    """Extend ``vars_dict`` with ``extra-vars``

    :param vars_dict: Dictionary to merge extra-vars into
    :param extra_vars: List of extra-vars
    """
    if extra_vars is None:
        return vars_dict
    for key, value in extra_vars.items():
        if key not in vars_dict:
            vars_dict[key] = value
        else:
            vars_dict[key] += value
    return vars_dict

def merge_extra_vars(vars_dict, extra_vars):
    if extra_vars:
        vars_dict.update(extra_vars)
    return vars_dict

def merge_extra_vars(vars_dict: dict, extra_vars: list = None):
    """Extend ``vars_dict`` with ``extra-vars``

    :param vars_dict: Dictionary to merge extra-vars into
    :param extra_vars: List of extra-vars
    """
    if extra_vars is not None:
        for key, val in extra_vars.items():
            if key not in vars_dict:
                vars_dict[key] = val
            else:
                if isinstance(vars_dict[key], dict) and isinstance(val, dict):
                    vars_dict[key] = merge_extra_vars(vars_dict[key], val)
                elif isinstance(vars_dict[key], list) and isinstance(val, list):
                    vars_dict[key] += val
                else:
                    vars_dict[key] = val
    return vars_dict

def ansible_playbook(ir_workspace, ir_plugin, playbook_path, verbose=None, extra_vars=None, ansible_args=None):
    """Wraps the 'ansible-playbook' CLI.

    :param ir_workspace: An Infrared Workspace object represents the active workspace
    :param ir_plugin: An InfraredPlugin object of the current plugin
    :param playbook_path: the playbook to invoke
    :param verbose: Ansible verbosity level
    :param extra_vars: dict. Passed to Ansible as extra-vars
    :param ansible_args: dict of ansible-playbook arguments to plumb down directly to Ansible.
    """
    workspace = ir_workspace.workspace
    plugin = ir_plugin.plugin
    if not playbook_path:
        raise ValueError("A playbook path is required.")
    if not os.path.isfile(playbook_path):
        raise ValueError("The playbook path does not exist.")
    if not os.path.isabs(playbook_path):
        playbook_path = os.path.join(workspace.base_dir, playbook_path)
    if verbose is None:
        verbose = ir_workspace.verbose
    if extra_vars is None:
        extra_vars = plugin.extra_vars
    if ansible_args is None:
        ansible_args = plugin.ansible_args
    command = ["ansible-playbook", playbook_path]
    if verbose:
        command.append("-" + "v" * verbose)
    if extra_vars:
        command.extend(["-e", json.dumps(extra_vars)])
    if ansible_args:
        command.extend(["-" + arg for arg in ansible_args])
    subprocess.run(command, check=True)

def _convert_non_cli_args(self, parser_name, values_dict):
    """Casts arguments to correct types by modifying values_dict param.

    By default all the values are strings.

    :param parser_name: The command name, e.g. main, virsh, ospd, etc
    :param values_dict: The dict of with arguments
    """
    parser = self._get_parser(parser_name)
    for key, value in values_dict.items():
        arg = parser._option_string_actions[key]
        if arg.type is not None:
            try:
                values_dict[key] = arg.type(value)
            except ValueError as e:
                raise ArgumentTypeError(f"{key}: {e}") from e

def get_plugin_spec_flatten_dict(plugin_dir):
    """Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    plugin_spec = load_plugin_spec(plugin_dir)
    flatten_dict = {}
    for prop_name, prop_value in plugin_spec.items():
        flatten_dict[prop_name] = prop_value
    return flatten_dict

def get_plugin_spec_flatten_dict(plugin_dir):
    """Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    plugin_spec = {}
    with open(os.path.join(plugin_dir, 'plugin_spec.yaml')) as f:
        plugin_spec = yaml.safe_load(f)
    flat_dict = {}
    for k, v in plugin_spec.items():
        if isinstance(v, dict):
            for sub_k, sub_v in v.items():
                flat_dict[f"{k}.{sub_k}"] = sub_v
        else:
            flat_dict[k] = v
    return flat_dict

